parameters.jsCode:
const src = $json.output ?? $json;
const title = String(src.recommended_title ?? '').trim();
const description = String(src.description ?? '').trim();
const tags = Array.isArray(src.tags) ? src.tags.map(x => String(x).trim()).filter(Boolean) : [];
const titleOptions = Array.isArray(src.title_options) ? src.title_options.map(x => String(x).trim()).filter(Boolean) : [];
const shorts = Array.isArray(src.shorts_ideas) ? src.shorts_ideas : [];
let needsReview = Boolean(src.needs_review);
const reasons = [];
if (src.review_reason) reasons.push(String(src.review_reason));
if (!title) { needsReview = true; reasons.push('Recommended title is missing'); }
if ([...title].length > 100) { needsReview = true; reasons.push('Recommended title exceeds 100 characters'); }
const descBytes = Buffer.byteLength(description, 'utf8');
if (descBytes > 5000) { needsReview = true; reasons.push('Description exceeds 5000 UTF-8 bytes'); }
const tagString = tags.join(',');
if ([...tagString].length > 500) { needsReview = true; reasons.push('Tags exceed 500 characters'); }
if (titleOptions.length < 5) { needsReview = true; reasons.push('Fewer than 5 title options'); }
if (shorts.length !== 3) { needsReview = true; reasons.push('Shorts ideas must contain exactly 3 items'); }
return [{json:{...src,recommended_title:title,description,tags,title_options:titleOptions,shorts_ideas:shorts,description_bytes:descBytes,needs_review:needsReview,review_reason:[...new Set(reasons)].filter(Boolean).join(' | ')}}];
